CREATE TABLE IF NOT EXISTS mail_binding(
                message_id TEXT PRIMARY KEY,kind TEXT NOT NULL,principal TEXT NOT NULL,source_id TEXT,report_id TEXT,
                source_record TEXT,profile TEXT,request TEXT,binding_hash TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS relations (id TEXT PRIMARY KEY, owner TEXT NOT NULL, doc TEXT NOT NULL,
                    chunk INTEGER NOT NULL, subject TEXT NOT NULL, predicate TEXT NOT NULL, object TEXT NOT NULL,
                    valid_from TEXT, valid_to TEXT, evidence TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS workers (id TEXT PRIMARY KEY, host TEXT NOT NULL, pid INTEGER NOT NULL,
                    started TEXT NOT NULL, beat TEXT NOT NULL, state TEXT NOT NULL, current TEXT,
                    processed INTEGER NOT NULL DEFAULT 0);

CREATE TABLE IF NOT EXISTS events(
                    seq INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT NOT NULL,
                    at TEXT NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS runs (
            id TEXT PRIMARY KEY, task TEXT NOT NULL, started_at TEXT NOT NULL,
            finished_at TEXT, status TEXT NOT NULL, error TEXT);

CREATE TABLE IF NOT EXISTS exchange_calendars (
        market TEXT NOT NULL, session TEXT NOT NULL, source TEXT NOT NULL,
        certified_at TEXT NOT NULL, PRIMARY KEY (market, session));

CREATE TABLE IF NOT EXISTS registry_evaluations (
        id TEXT PRIMARY KEY, model_version TEXT NOT NULL, owner TEXT NOT NULL,
        sha256 TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS retention_actions (
        action_id TEXT PRIMARY KEY, owner TEXT NOT NULL, model_version TEXT NOT NULL,
        action TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS stable_releases (
        version TEXT PRIMARY KEY, owner TEXT NOT NULL, authorized_at TEXT NOT NULL, note TEXT NOT NULL,
        revoked_at TEXT, revoke_reason TEXT);
